<script setup lang="ts">
import { computed,ref,watch } from 'vue';
import type { useAuth } from '../useAuth';
import type { useReview } from '../useReview';
import { correctionFields,correctionLabels,categoryLabels,correctionStatuses,currentValue,fieldInput,formatValue,inputValue,nullableFields,reviewLabel } from '../corrections';
import type { Basis,Correction } from '../corrections';
import type { Work } from '../types';
import CorrectionDialog from './CorrectionDialog.vue';
import CorrectionValue from './CorrectionValue.vue';
import CatalogPagination from './CatalogPagination.vue';
const props=defineProps<{auth:ReturnType<typeof useAuth>;review:ReturnType<typeof useReview>}>();
const emit=defineEmits<{back:[];changed:[]}>();
const r=props.review,proactive=ref<Work|null>(null),reason=ref(''),action=ref('approve'),confirming=ref(false),validation=ref(''),mediaHold=ref(false),clearMedia=ref(false),mediaBasis=ref('');
type Draft={field:string;value:string;kind:'quoted'|'not_stated';source_url:string;source_text:string;quote:string};
const changes=ref<Draft[]>([]);
const actionLabels:Record<string,string>={approve:'采纳修正／确认字段',reject:'未采纳',rebase:'更新核对基准',pause:'暂不能用于推荐',restore:'恢复作品展示'};
const locked=computed(()=>r.busy.value||r.unknown.value),pages=computed(()=>Math.max(1,Math.ceil(r.total.value/20)));
const report=computed(()=>r.detail.value?.correction);
function draft(field:string):Draft{const d=r.detail.value!;const suggestion=d.correction?.field===field?d.correction.suggestion:null;const unknown=suggestion?.kind==='unknown';return {field,value:['preview_mapping','source_link','work_identity'].includes(field)?'unavailable':inputValue(suggestion?.kind==='set'?suggestion.value:currentValue(d.work,field)),kind:unknown?'not_stated':'quoted',source_url:d.work.source_url,source_text:d.work.original_intro,quote:''};}
const allowed=computed(()=>{const f=report.value?.field;if(!f)return [];return [...new Set([f,...(correctionFields.mapping.includes(f)?[]:['original_intro','summary']),...(['content_type','episode_count','chapter_count'].includes(f)?['content_type','episode_count','chapter_count']:[])])];});
watch(r.detail,()=>{reason.value='';confirming.value=false;validation.value='';mediaHold.value=false;clearMedia.value=false;mediaBasis.value='';action.value=report.value?(report.value.status==='needs_recheck'?'rebase':['accepted','rejected'].includes(report.value.status)?'pause':'approve'):'pause';changes.value=report.value?[draft(report.value.field)]:[];});
watch([reason,action,changes,mediaHold,clearMedia,mediaBasis],()=>confirming.value=false,{deep:true});
watch(r.changed,()=>emit('changed'));
watch(r.mode,()=>{r.detail.value=null;r.page.value=1;void r.load();});
void r.load();
function filter(){r.page.value=1;void r.load();}function turn(value:number){r.page.value=value;void r.load();}
function open(item:Correction|Work){void r.open(item.id,r.mode.value==='works');}
function reload(){const d=r.detail.value;if(d)void r.open(d.correction?.id||d.work.id,!d.correction);}
function changeField(index:number){changes.value[index]=draft(changes.value[index].field);}
const payload=computed(()=>{const d=r.detail.value;if(!d)return null;const base={reason:reason.value.trim(),expected_work_revision:d.work.review?.revision};if(['pause','restore'].includes(action.value))return {...base,action:action.value,media_hold:mediaHold.value,clear_media_hold:clearMedia.value?{kind:'quoted',source_url:mediaBasis.value.split('\n')[0],source_text:mediaBasis.value.split('\n').slice(1).join('\n'),quote:mediaBasis.value.split('\n').slice(1).join('\n')}:null,related_correction_id:d.correction?.id||null};if(!d.correction)return null;const common={reason:base.reason,expected_report_revision:d.correction.revision,action:action.value};if(action.value==='reject')return common;if(action.value==='rebase')return {...common,expected_work_revision:base.expected_work_revision};return {...common,expected_work_revision:base.expected_work_revision,media_hold:mediaHold.value,changes:changes.value.map(c=>({field:c.field,value:c.kind==='not_stated'?null:fieldInput(c.field,c.value),basis:{kind:c.kind,source_url:c.source_url,source_text:c.source_text,quote:c.kind==='not_stated'?null:c.quote}}))};});
function review(){validation.value='';try{if(!reason.value.trim()||Array.from(reason.value.trim()).length>500)throw Error('请填写 1～500 字符处理理由');const p=payload.value;if(!p)throw Error('请先建立核对单');if(action.value==='approve'){if(!changes.value.length)throw Error('请添加修正字段');for(const c of changes.value){if(c.kind==='not_stated'&&!nullableFields.includes(c.field))throw Error('此字段不能恢复未知');if(c.kind==='quoted'&&(!c.quote.trim()||!c.source_text.includes(c.quote)))throw Error('逐字摘录须存在于所核对原文');}}confirming.value=true;}catch(exc){validation.value=exc instanceof Error?exc.message:'请检查核对内容';}}
async function publish(){const d=r.detail.value;if(!confirming.value||!d)return;const p=payload.value;if(!p)return;confirming.value=false;await r.action(['pause','restore'].includes(action.value)?`/api/v1/me/review/works/${d.work.id}/availability`:`/api/v1/me/review/corrections/${d.correction!.id}/actions`,p);}
function submitted(row:Correction){proactive.value=null;void r.open(row.id);}
</script>
<template>
<section class="review-workspace" aria-labelledby="review-title"><header class="space-heading"><h1 id="review-title">资料审核工作台</h1><button class="text-button" @click="emit('back')">返回个人空间</button></header>
<p class="source-note">仅记录本次核对的字段及来源范围，不代表观看完整剧集或独立双人复核。</p><p v-if="locked" role="status">请求仍可能在服务端完成，离开页面不会撤销；请从审核记录核对结果。</p>
<p v-if="!r.canReview.value" class="field-error" role="alert">审核权限不可用。{{r.accessError.value}}<button @click="r.checkAccess">重新核对权限</button></p>
<template v-else><fieldset :disabled="locked" class="review-filters"><label>查看范围<select v-model="r.mode.value"><option value="corrections">用户与主动核对单</option><option value="works">作品主动核对</option></select></label>
<label v-if="r.mode.value==='corrections'">处理状态<select v-model="r.status.value" @change="filter"><option v-for="(label,key) in correctionStatuses" :value="key">{{label}}</option></select></label>
<label v-if="r.mode.value==='corrections'">问题类别<select v-model="r.category.value" @change="filter"><option value="">全部类别</option><option v-for="(label,key) in categoryLabels" :value="key">{{label}}</option></select></label>
<label v-else>核对范围<select v-model="r.reviewState.value" @change="filter"><option value="automatic">自动整理</option><option value="partial">已核对部分字段</option><option value="recheck">待重新核对</option><option value="unavailable">暂不可用</option><option value="all">全部作品</option></select></label><form @submit.prevent="filter"><label for="review-search">作品名称</label><input id="review-search" v-model="r.query.value" maxlength="100"><button>筛选</button></form><button @click="r.load">刷新列表</button></fieldset>
<p v-if="r.error.value" class="field-error" role="alert">{{r.error.value}} <button @click="r.load">重试列表</button></p><p v-else-if="r.loading.value" role="status">正在读取审核列表…</p><p v-else-if="!r.items.value.length">当前范围没有待核对记录。</p>
<div class="review-list"><button v-for="item in r.items.value" :key="item.id" :disabled="locked" @click="open(item)"><strong>{{'work_title' in item?item.work_title:item.title}}</strong><span>{{'status' in item?correctionStatuses[item.status]:reviewLabel(item)}}</span><small v-if="'field' in item">{{correctionLabels[item.field]}}</small></button></div><CatalogPagination :page="r.page.value" :pages="pages" :busy="r.loading.value||locked" @change="turn"/>
<p v-if="r.detailLoading.value" role="status">正在读取核对资料…</p><p v-if="r.detailError.value" class="field-error" role="alert">{{r.detailError.value}}</p><p v-if="r.notice.value" role="status">{{r.notice.value}}</p>
<article v-if="r.detail.value" class="review-card review-detail"><header><h2>{{r.detail.value.work.title}}</h2><button :disabled="locked" @click="reload">重新读取最新资料</button></header><p>{{reviewLabel(r.detail.value.work)}} · 资料版本 {{r.detail.value.work.review?.revision}} · {{new Date(r.detail.value.updated_at).toLocaleString('zh-CN')}}</p>
<p v-if="r.detail.value.manual_hold">暂时停用：{{r.detail.value.hold_reason}}</p><p v-if="r.detail.value.media_hold">视频预览已暂停，恢复作品不会自动解除错误素材限制。</p>
<div class="review-compare"><section><h3>最新来源原文</h3><p>{{r.detail.value.source_snapshot.data.original_intro}}</p><details><summary>来源字段与依据</summary><pre>{{JSON.stringify(r.detail.value.source_snapshot.data,null,2)}}</pre></details></section><section><h3>当前有效资料</h3><dl><template v-for="field in ['title','original_intro','summary','content_type','episode_count','chapter_count','genres','themes','pace','harem','romance','tragic']"><dt>{{correctionLabels[field]}}</dt><dd>{{formatValue(currentValue(r.detail.value.work,field))}}</dd></template></dl></section></div>
<template v-if="report"><h3>纠错建议与原基准</h3><p>{{correctionStatuses[report.status]}} · {{correctionLabels[report.field]}} · 基准版本 {{report.base_revision}}</p><p>{{report.description}}</p><p>提交时原值：{{formatValue(report.current_value)}} → 建议：{{report.suggestion.kind==='unknown'?'未知':report.suggestion.kind==='issue'?'核对对应关系':formatValue(report.suggestion.value)}}</p><p v-if="report.source_hint">来源线索：<a v-if="report.source_hint.url" :href="report.source_hint.url" target="_blank" rel="noopener noreferrer">查看线索</a> {{report.source_hint.quote}}</p><details><summary>查看原基准全部资料</summary><pre>{{JSON.stringify(r.detail.value.base_snapshot,null,2)}}</pre></details><p v-if="report.decision">处理说明：{{report.decision}}</p></template>
<button v-else class="secondary-button" :disabled="locked" @click="proactive=r.detail.value.work">主动建立核对单</button>
<form class="correction-form" @submit.prevent="review"><fieldset :disabled="locked"><label for="review-action">处理方式</label><select id="review-action" v-model="action"><template v-if="report&&['pending','needs_recheck'].includes(report.status)"><option v-if="report.status==='pending'" value="approve">采纳修正／确认字段</option><option value="reject">未采纳</option><option v-if="report.status==='needs_recheck'" value="rebase">明确核对最新资料，更新报告基准</option></template><option value="pause">暂不能用于推荐</option><option value="restore">重新核对后恢复作品</option></select>
<template v-if="action==='approve'&&report"><section v-for="(c,i) in changes" :key="i" class="review-change"><label :for="'change-field-'+i">核对字段 {{i+1}}</label><select :id="'change-field-'+i" v-model="c.field" @change="changeField(i)"><option v-for="f in allowed" :value="f">{{correctionLabels[f]}}</option></select><p>原值：{{formatValue(currentValue(r.detail.value.work,c.field))}}</p><label :for="'basis-kind-'+i">依据类型</label><select :id="'basis-kind-'+i" v-model="c.kind"><option value="quoted">来源明确说明</option><option v-if="nullableFields.includes(c.field)" value="not_stated">资料未说明，恢复未知</option></select><template v-if="c.kind==='quoted'"><label :for="'change-value-'+i">核对后的值</label><CorrectionValue :field="c.field" v-model="c.value" :id="'change-value-'+i"/></template><label :for="'basis-url-'+i">已核对来源</label><input :id="'basis-url-'+i" v-model="c.source_url" maxlength="1000"><label :for="'basis-text-'+i">所核对来源原文</label><textarea :id="'basis-text-'+i" v-model="c.source_text" maxlength="6000" rows="4"/><template v-if="c.kind==='quoted'"><label :for="'basis-quote-'+i">逐字摘录</label><textarea :id="'basis-quote-'+i" v-model="c.quote" maxlength="1000" rows="2"/></template><button v-if="i>0" type="button" @click="changes.splice(i,1)">移除此关联项</button></section><button v-if="changes.length<5&&allowed.length>changes.length" type="button" @click="changes.push(draft(allowed.find(f=>!changes.some(c=>c.field===f))!))">添加必要关联字段</button></template>
<label v-if="['pause','approve'].includes(action)"><input type="checkbox" v-model="mediaHold">同时暂停错误视频预览</label>
<template v-if="action==='restore'&&r.detail.value.media_hold"><label><input type="checkbox" v-model="clearMedia">已明确核对现有首集资产与本作映射，解除视频限制</label><label v-if="clearMedia">第一行为已登记首集来源链接，其后为核对原文<textarea v-model="mediaBasis" rows="3"/></label></template>
<label for="review-reason">处理理由（必填）</label><textarea id="review-reason" v-model="reason" maxlength="1000" rows="3"/><small>{{Array.from(reason.trim()).length}} / 500 字符</small></fieldset>
<p v-if="validation||r.actionError.value" class="field-error" role="alert">{{validation||r.actionError.value}}</p>
<div v-if="r.unknown.value" class="review-actions"><button type="button" :disabled="r.busy.value" @click="r.resolve">核对审核回执</button><button type="button" :disabled="r.busy.value" @click="r.retry">使用原标识重试</button></div>
<button v-else-if="!confirming" class="primary-button" :disabled="locked">{{r.busy.value?'正在处理…':'核对本次变更'}}</button>
<section v-if="confirming" class="review-confirm" aria-label="发布前核对"><h3>确认本次处理：{{actionLabels[action]}}</h3><p>处理理由：{{reason.trim()}}</p><template v-if="action==='approve'"><div v-for="c in changes" class="review-confirm-change"><h4>{{correctionLabels[c.field]}}</h4><p>{{formatValue(currentValue(r.detail.value.work,c.field))}} → {{c.kind==='not_stated'?'未知':formatValue(fieldInput(c.field,c.value))}}</p><p>依据：{{c.kind==='not_stated'?'所核对资料未说明，不能据此认定不存在':c.quote}}</p><a :href="c.source_url" target="_blank" rel="noopener noreferrer">已核对来源</a></div><p>其余字段保持当前值，仅记录上列核对范围。</p></template><p v-if="action==='rebase'">已核对最新资料及旧建议，本次只更新报告基准，仍需单独确认采纳。</p><p v-if="action==='pause'">暂停公开展示和推荐，已有收藏、反馈与历史记录继续保留。</p><p v-if="action==='restore'">恢复使用已核对的有效资料；视频限制按本次明确选择处理。</p><p v-if="mediaHold">同时暂停视频预览。</p><button class="primary-button" type="button" :disabled="locked" @click="publish">确认处理并保存</button><button type="button" @click="confirming=false">返回修改</button></section>
</form><details><summary>已确认字段与依据</summary><pre>{{JSON.stringify(r.detail.value.confirmed_fields,null,2)}}</pre></details><details><summary>修改与核对记录</summary><pre>{{JSON.stringify(r.detail.value.events,null,2)}}</pre></details>
</article></template>
<CorrectionDialog v-if="proactive" :auth="auth" :work="proactive" reviewer @close="proactive=null" @submitted="submitted" @records="proactive=null" @forbidden="proactive=null;r.loseAccess()"/>
</section>
</template>
